  /// the default (same id ⇒ no swap). May be absent on older rows.
  final String? orgIngredientId;

  const RecipeLineView({
    required this.ingredientName,
    required this.quantity,
    required this.unit,
    this.sizeLabel,
    required this.category,
    this.orgIngredientId,
  });

  @override
  int get hashCode =>
      ingredientName.hashCode ^
      quantity.hashCode ^
      unit.hashCode ^
      sizeLabel.hashCode ^
      category.hashCode ^
      orgIngredientId.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RecipeLineView &&
          runtimeType == other.runtimeType &&
          ingredientName == other.ingredientName &&
          quantity == other.quantity &&
          unit == other.unit &&
          sizeLabel == other.sizeLabel &&
          category == other.category &&
          orgIngredientId == other.orgIngredientId;
}

/// One preparation step: localized, and pointing at the animation's CACHED
/// file so the sheet plays it with no network.
class RecipeStepView {
  final String name;
  final String? note;

  /// On-disk path of the cached animation — `None` for a written step, and
  /// until the animation has been downloaded by a sync.
  final String? localAnimationPath;
  final String? animationUrl;

  const RecipeStepView({
    required this.name,
    this.note,
    this.localAnimationPath,
    this.animationUrl,
  });

  @override
  int get hashCode =>
      name.hashCode ^
      note.hashCode ^
      localAnimationPath.hashCode ^
      animationUrl.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RecipeStepView &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          note == other.note &&
          localAnimationPath == other.localAnimationPath &&
          animationUrl == other.animationUrl;
}
